begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('60000000-0000-4000-8000-000000000001','finance-owner@example.invalid'),('60000000-0000-4000-8000-000000000002','finance-other@example.invalid');
delete from private.app_owner;
insert into private.app_owner(user_id,github_user_id) values('60000000-0000-4000-8000-000000000001','60001');
select ok(not has_table_privilege('anon','public.finance_transactions','SELECT'),'anon Finance denied');
select ok(not has_table_privilege('anon','public.learning_habits','SELECT'),'anon Learning denied');
select ok(not has_table_privilege('authenticated','public.learning_checkins','INSERT'),'direct check-in insert denied');
select ok(not has_table_privilege('authenticated','public.learning_checkins','UPDATE'),'direct check-in update denied');
select ok(not has_table_privilege('authenticated','public.learning_checkins','DELETE'),'direct check-in delete denied');
select ok(not has_column_privilege('authenticated','public.finance_accounts','revision','UPDATE'),'direct finance revision denied');
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
insert into public.finance_settings(id) values(auth.uid());
insert into public.finance_accounts(id,name,opening) values('61000000-0000-4000-8000-000000000001','source',-100),('61000000-0000-4000-8000-000000000002','target',200);
insert into public.finance_categories(id,code,name,kind) values('62000000-0000-4000-8000-000000000001','food','Food','expense'),('62000000-0000-4000-8000-000000000002','salary','Salary','income');
select is((select opening from public.finance_accounts_dto where name='source'),'-100','money DTO text negative opening');
select lives_ok($$insert into public.finance_transactions(id,date,description,amount,kind,account_id,destination_account_id,source) values(gen_random_uuid(),(now() at time zone 'Asia/Ho_Chi_Minh')::date,'transfer',100,'transfer','61000000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000002','manual')$$,'valid transfer');
select throws_ok($$insert into public.finance_transactions(id,date,description,amount,kind,account_id,category_id,source) values(gen_random_uuid(),(now() at time zone 'Asia/Ho_Chi_Minh')::date,'bad',100,'expense','61000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000002','manual')$$,'23514',null,'expense category kind enforced');
select throws_ok($$insert into public.finance_budgets(id,category_id,name) values(gen_random_uuid(),'62000000-0000-4000-8000-000000000002','bad')$$,'23514',null,'income category cannot be budget');
select lives_ok($$insert into public.finance_transactions(id,date,description,amount,kind,account_id,category_id,source) values(gen_random_uuid(),(now() at time zone 'Asia/Ho_Chi_Minh')::date,'expense',10,'expense','61000000-0000-4000-8000-000000000001','62000000-0000-4000-8000-000000000001','manual')$$,'expense history');
select throws_ok($$update public.finance_categories set kind='income' where code='food'$$,'23514',null,'history category meaning immutable');
select throws_ok($$delete from public.finance_accounts where name='source'$$,'23503',null,'account history RESTRICT');
select throws_ok($$insert into public.finance_budgets(id,category_id,name,default_limit) values(gen_random_uuid(),'62000000-0000-4000-8000-000000000001','bad',-1)$$,'23514',null,'negative budget denied');
insert into public.learning_habits(id,title,target_minutes) values('63000000-0000-4000-8000-000000000001','Learn',15);
select lives_ok($$select public.learning_checkin('63000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000001',0,20,'note',false,(now() at time zone 'Asia/Ho_Chi_Minh')::date)$$,'owner check-in');
select throws_ok($$select public.learning_checkin('63000000-0000-4000-8000-000000000001',gen_random_uuid(),0,20,'note',false,(now() at time zone 'Asia/Ho_Chi_Minh')::date)$$,'P0001','conflict','unique date CAS');
select lives_ok($$select public.learning_checkin('63000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000001',1,30,'edited',false,(now() at time zone 'Asia/Ho_Chi_Minh')::date)$$,'same day replaces');
select throws_ok($$select public.learning_checkin('63000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000001',1,1,'',true,(now() at time zone 'Asia/Ho_Chi_Minh')::date)$$,'P0001','conflict','stale undo blocked');
update public.learning_habits set archived=true;
select throws_ok($$select public.learning_checkin('63000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000001',2,20,'note',false,(now() at time zone 'Asia/Ho_Chi_Minh')::date)$$,'23514','archived','archived direct RPC blocked');
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.finance_accounts_dto),0,'non-owner view invisible');
select is((select count(*)::int from public.finance_transactions),0,'non-owner Finance invisible');
select is((select count(*)::int from public.learning_habits),0,'non-owner habits invisible');
select is((select count(*)::int from public.learning_checkins),0,'non-owner entries invisible');
select throws_ok($$insert into public.finance_accounts(id,name) values(gen_random_uuid(),'bad')$$,'42501',null,'non-owner finance insert denied');
select throws_ok($$select public.finance_import(gen_random_uuid(),'[]')$$,'42501',null,'non-owner import denied');
select throws_ok($$select public.learning_checkin('63000000-0000-4000-8000-000000000001',gen_random_uuid(),0,1,'',false,(now() at time zone 'Asia/Ho_Chi_Minh')::date)$$,'42501',null,'non-owner check-in denied');
select throws_ok($$insert into public.learning_habits(id,title,target_minutes) values(gen_random_uuid(),'bad',1)$$,'42501',null,'non-owner habit insert denied');
reset role;
-- FK rejects cross-owner references even for trusted SQL inserts.
select throws_ok($$insert into public.finance_transactions(id,owner_id,date,description,amount,kind,account_id,destination_account_id,source) values(gen_random_uuid(),'60000000-0000-4000-8000-000000000002',(now() at time zone 'Asia/Ho_Chi_Minh')::date,'bad',1,'transfer','61000000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000002','manual')$$,'23503',null,'cross-owner account FK');
select throws_ok($$insert into public.learning_checkins(id,owner_id,habit_id,checked_on,minutes) values(gen_random_uuid(),'60000000-0000-4000-8000-000000000002','63000000-0000-4000-8000-000000000001',(now() at time zone 'Asia/Ho_Chi_Minh')::date,1)$$,'23503',null,'cross-owner habit FK');
update private.app_owner set enabled=false;
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select is((select count(*)::int from public.finance_accounts),0,'disabled owner finance invisible');
select is((select count(*)::int from public.learning_checkins),0,'disabled owner learning invisible');
reset role;
select * from finish();
rollback;
